DROP TABLE IF EXISTS `tempat_wisata`;
CREATE TABLE `tempat_wisata` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kabupaten` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kecamatan` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kelompok` enum('Daya Tarik','Amenitas') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sub_kategori` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rating` decimal(3,1) DEFAULT '0.0',
  `ulasan` int DEFAULT '0',
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `status_verifikasi` enum('Resmi','Usulan Baru') COLLATE utf8mb4_unicode_ci DEFAULT 'Resmi',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_kabupaten` (`kabupaten`),
  KEY `idx_kecamatan` (`kecamatan`),
  KEY `idx_kelompok` (`kelompok`),
  KEY `idx_sub_kategori` (`sub_kategori`),
  KEY `idx_status` (`status_verifikasi`)
) ENGINE=InnoDB AUTO_INCREMENT=876 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

